def ppo_trace_bytes(data) -> bytes:
    """将一份 PPO 轨迹结构严格校验后序列化为单行 JSON 字节。

    data 须为 dict，否则抛 TypeError；其余任何违约均抛 ValueError。
    顶层键序须恰为 episodes、success_rate；episodes 为非空 list，
